// Command psi-kinds generates psi/kinds_gen.go from psi/kinds.txt.
//
// psi/kinds.txt is append-only: a kind's number is its line position, and
// linters may persist kind numbers, so names are never removed or reordered.
// A kind Kotlin renames is renamed in place, keeping its number; a kind
// Kotlin drops stays, never produced, so no later kind reuses its number.
//
// Usage, from the repository root:
//
//	go run ./cmd/psi-kinds          # regenerate
//	go run ./cmd/psi-kinds -check   # fail if the generated file is stale
package main

import (
	"bytes"
	"crypto/sha256"
	"flag"
	"fmt"
	"go/format"
	"os"
	"strings"
)

const (
	input  = "psi/kinds.txt"
	output = "psi/kinds_gen.go"
)

func main() {
	check := flag.Bool("check", false, "verify the generated file without writing it")
	flag.Parse()
	raw, err := os.ReadFile(input)
	if err != nil {
		fail(err)
	}
	names := strings.Fields(string(raw))
	seen := map[string]bool{}
	for _, n := range names {
		if seen[n] {
			fail(fmt.Errorf("%s: duplicate kind %s", input, n))
		}
		seen[n] = true
	}
	var b strings.Builder
	b.WriteString("// Code generated by go run ./cmd/psi-kinds; DO NOT EDIT.\n\npackage psi\n\n")
	fmt.Fprintf(&b, "// KindsHash is the SHA-256 of psi/kinds.txt.\nconst KindsHash = %q\n\n", fmt.Sprintf("%x", sha256.Sum256(raw)))
	b.WriteString("// Kind identifies a node's element type. Numbers are stable across releases.\ntype Kind uint16\n\n")
	b.WriteString("// Element kinds, in psi/kinds.txt order.\nconst (\n\tKindUnknown Kind = iota\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\tKind%s\n", n)
	}
	b.WriteString(")\n\nvar kindNames = [...]string{\"\",\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\t%q,\n", n)
	}
	b.WriteString(`}

// KindCount is one more than the largest Kind.
const KindCount = len(kindNames)

var kindsByName = func() map[string]Kind {
	m := make(map[string]Kind, len(kindNames))
	for i, name := range kindNames {
		m[name] = Kind(i)
	}
	return m
}()

// KindForName returns the kind with the given name, or KindUnknown.
func KindForName(name string) Kind { return kindsByName[name] }

// String returns the kind's name, or "" for an unknown kind.
func (k Kind) String() string {
	if int(k) >= len(kindNames) {
		return ""
	}
	return kindNames[k]
}
`)
	src, err := format.Source([]byte(b.String()))
	if err != nil {
		fail(err)
	}
	if *check {
		old, err := os.ReadFile(output)
		if err != nil {
			fail(err)
		}
		if !bytes.Equal(old, src) {
			fail(fmt.Errorf("%s is stale; run go run ./cmd/psi-kinds", output))
		}
		return
	}
	if err := os.WriteFile(output, src, 0o644); err != nil {
		fail(err)
	}
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, "psi-kinds:", err)
	os.Exit(1)
}
